package corpus.collapse

fun sendOrWait(ready: Boolean, permitted: Boolean, send: () -> Unit, waitForReady: () -> Unit) {
    if (ready) {
        if (permitted) send()
    } else {
        waitForReady()
    }
}

package corpus.collapse

fun sendOrDeny(ready: Boolean, permitted: Boolean, send: () -> Unit, deny: () -> Unit) {
    if (ready) {
        if (permitted) send() else deny()
    }
}

package corpus.collapse

fun sendIfAllowed(ready: Boolean, permitted: Boolean, send: () -> Unit) {
    if (ready) if (permitted) send()
}
